\set ON_ERROR_STOP on
-- New synthetic fixture only; use an already migrated owned loopback cluster.
begin;
set timezone='UTC';
create schema song_editor_test;
create function song_editor_test.id(n integer) returns uuid language sql immutable as $$select ('99700000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid$$;
create table song_editor_test.ids(name text primary key,id uuid);
create table song_editor_test.editor_cases(name text primary key,context jsonb);
create table song_editor_test.proposal_cases(name text primary key,request jsonb,receipt jsonb);
create table song_editor_test.pending(name text primary key,command jsonb);
grant usage on schema song_editor_test to authenticated;
grant select,insert on all tables in schema song_editor_test to authenticated;
insert into auth.users(id,email) select song_editor_test.id(n),'song-editor-'||n||'@example.test' from generate_series(1,5)n;
select set_config('request.jwt.claim.sub',song_editor_test.id(1)::text,false);
set role authenticated;
insert into song_editor_test.ids select 'team',team_id from public.create_team_workspace('Song Editor Team','SE-61025');
reset role;
select set_config('request.jwt.claim.sub','',false);
create function song_editor_test.team() returns uuid language sql stable as $$select id from song_editor_test.ids where name='team'$$;
insert into public.team_members(id,team_id,profile_id,role,status) select song_editor_test.id(10+n),song_editor_test.team(),song_editor_test.id(n),case when n=5 then 'admin'::public.team_role else 'member'::public.team_role end,'active' from unnest(array[2,3,5])n;
select set_config('request.jwt.claim.sub',song_editor_test.id(4)::text,false);
set role authenticated;
insert into song_editor_test.ids select 'foreign',team_id from public.create_team_workspace('Other Song Editor Team','SF-61025');
reset role;
select set_config('request.jwt.claim.sub','',false);
insert into public.songs(id,team_id,created_by,title,artist,original_key,bpm,time_signature,lyrics_chords,created_at) values(song_editor_test.id(100),song_editor_test.team(),song_editor_test.id(2),'Actual creator song','Artist','C',100,'4/4','Preserved original lyrics','2026-10-25T01:02:03.123456Z');
create function song_editor_test.value(s public.songs) returns jsonb language sql as $$select jsonb_build_object('title',s.title,'artist',s.artist,'original_key',s.original_key,'bpm',s.bpm,'time_signature',s.time_signature,'lyrics_chords',s.lyrics_chords,'youtube_url',s.youtube_url,'spotify_url',s.spotify_url,'image_url',s.image_url,'album',s.album,'tags',s.tags)$$;
create function song_editor_test.capture_editor(label text) returns jsonb language plpgsql as $$declare m public.team_members%rowtype;s public.songs%rowtype;override boolean;direct boolean;raw jsonb;context jsonb;begin
 select * into m from public.team_members where team_id=song_editor_test.team() and profile_id=auth.uid() and status='active';assert found,'Actual current member missing';
 select * into s from public.songs where id=song_editor_test.id(100) and team_id=m.team_id and status='approved' and deleted_at is null;assert found,'Actual active approved song hidden';
 -- Exact SELECT used by the protected editor reader; authenticated self RLS applies.
 select coalesce(jsonb_agg(to_jsonb(o) order by o.id),'[]'::jsonb) into raw from public.team_permission_overrides o where team_id=m.team_id and permission='songs.edit' and(role=m.role or member_id=m.id);
 if m.role<>'owner' then select coalesce((select (r->>'allowed')::boolean from jsonb_array_elements(raw)r where r->>'member_id'=m.id::text),(select (r->>'allowed')::boolean from jsonb_array_elements(raw)r where r->>'role'=m.role::text)) into override;end if;
 direct:=case when m.role='owner' then true else coalesce(override,m.role='admin' or s.created_by=auth.uid()) end;
 context:=jsonb_build_object('version',2,'identity',jsonb_build_object('userId',auth.uid(),'teamId',m.team_id,'memberId',m.id,'teamName','Song Editor Team','role',m.role,'permissions',case when private.has_team_permission(m.team_id,'songs.edit') then '["songs.edit"]'::jsonb else '[]'::jsonb end),'song',jsonb_build_object('id',s.id,'teamId',s.team_id,'createdAt',s.created_at,'createdBy',s.created_by,'revision',s.sync_revision,'value',song_editor_test.value(s)),'authorization',jsonb_build_object('direct',direct,'propose',not direct,'editOverride',override),'fetchedAt',clock_timestamp());
 insert into song_editor_test.editor_cases values(label,context);return context;
end$$;
create function song_editor_test.notification_count() returns bigint language sql security definer set search_path='' as $$select count(*) from public.notifications where team_id=song_editor_test.team() and title='Shared edit request'$$;
create function song_editor_test.download() returns jsonb language plpgsql as $$declare page jsonb;base jsonb;begin
 page:=public.mobile_download_page(song_editor_test.team(),jsonb_build_object('kind','song','id',song_editor_test.id(100)));
 select r into base from jsonb_array_elements(page->'records')r where r->>'entityType'='song' and r->>'id'=song_editor_test.id(100)::text;assert base is not null;return base;
end$$;
create function song_editor_test.command(n integer,base jsonb,title text) returns jsonb language sql as $$select jsonb_build_object('commandId',song_editor_test.id(n),'entityType','song','entityId',song_editor_test.id(100),'baseRevision',base->'revision','baseValue',base->'value','value',base->'value'||jsonb_build_object('title',title))$$;
create function song_editor_test.deny_command(command jsonb,expected text) returns void language plpgsql as $$declare denied boolean:=false;begin begin perform public.mobile_apply_command(song_editor_test.team(),command);exception when others then if sqlstate=expected then denied:=true;else raise;end if;end;assert denied,'Actual song command should be denied';end$$;
create function song_editor_test.proposal(n integer,revision bigint,changes jsonb default '{"title":"Proposed only"}') returns jsonb language sql as $$select jsonb_build_object('version',2,'intent',jsonb_build_object('version',2,'userId',auth.uid(),'teamId',m.team_id,'memberId',m.id,'proposal',jsonb_build_object('targetType','song','targetId',song_editor_test.id(100),'revision',revision,'changes',changes,'reason','Match current service plan','requestNonce',song_editor_test.id(n)))) from public.team_members m where team_id=song_editor_test.team() and profile_id=auth.uid() and status='active'$$;
create function song_editor_test.capture_proposal(label text,input jsonb) returns jsonb language plpgsql as $$declare p jsonb:=input#>'{intent,proposal}';v_id uuid;row public.shared_edit_requests%rowtype;receipt jsonb;begin
 v_id:=public.submit_shared_edit_request('song',(p->>'targetId')::uuid,(p->>'revision')::bigint,p->'changes',p->>'reason',(p->>'requestNonce')::uuid);
 select * into row from public.shared_edit_requests where shared_edit_requests.id=v_id and team_id=song_editor_test.team() and requested_by=auth.uid() and request_nonce=(p->>'requestNonce')::uuid;assert found,'Own proposal receipt hidden';
 receipt:=jsonb_build_object('version',2,'userId',input#>>'{intent,userId}','teamId',input#>>'{intent,teamId}','memberId',input#>>'{intent,memberId}','request',to_jsonb(row));
 insert into song_editor_test.proposal_cases values(label,input,receipt);return receipt;
end$$;
create function song_editor_test.deny_proposal(input jsonb,expected text) returns void language plpgsql as $$declare p jsonb:=input#>'{intent,proposal}';denied boolean:=false;begin begin perform public.submit_shared_edit_request('song',(p->>'targetId')::uuid,(p->>'revision')::bigint,p->'changes',p->>'reason',(p->>'requestNonce')::uuid);exception when others then if sqlstate=expected then denied:=true;else raise;end if;end;assert denied,'Actual proposal should be denied';end$$;
select set_config('request.jwt.claim.sub',song_editor_test.id(2)::text,false);
set role authenticated;
select song_editor_test.capture_editor('creator-inherited-no-general-edit');
do $$declare base jsonb;command jsonb;result jsonb;begin
 assert not private.has_team_permission(song_editor_test.team(),'songs.edit'),'Ordinary creator unexpectedly has general editing';base:=song_editor_test.download();command:=song_editor_test.command(200,base,'Creator saved');
 result:=public.mobile_apply_command(song_editor_test.team(),command);assert result->>'status'='applied','Actual creator was rejected';assert public.mobile_apply_command(song_editor_test.team(),command)=result,'Exact edit retry differs';insert into song_editor_test.pending values('creator-applied',command);
 perform song_editor_test.deny_command(jsonb_set(command,'{commandId}',to_jsonb(song_editor_test.id(201)))||jsonb_build_object('value',command->'value'||jsonb_build_object('created_by',song_editor_test.id(3))),'22023');
end$$;
reset role;
select set_config('request.jwt.claim.sub',song_editor_test.id(3)::text,false);
set role authenticated;
select song_editor_test.capture_editor('noncreator-propose');
do $$declare base jsonb:=song_editor_test.download();begin perform song_editor_test.deny_command(song_editor_test.command(202,base,'Noncreator bypass'),'42501');end$$;
reset role;
select set_config('request.jwt.claim.sub',song_editor_test.id(1)::text,false);
set role authenticated;
select song_editor_test.capture_editor('owner-direct');
reset role;
select set_config('request.jwt.claim.sub',song_editor_test.id(5)::text,false);
set role authenticated;
select song_editor_test.capture_editor('admin-direct');
reset role;
select set_config('request.jwt.claim.sub','',false);
insert into public.team_permission_overrides(team_id,role,permission,allowed) values(song_editor_test.team(),'member','songs.edit',false);
select set_config('request.jwt.claim.sub',song_editor_test.id(2)::text,false);
set role authenticated;
select song_editor_test.capture_editor('creator-explicit-deny');
select song_editor_test.deny_command((select command from song_editor_test.pending where name='creator-applied'),'42501');
reset role;
select set_config('request.jwt.claim.sub','',false);
insert into public.team_permission_overrides(team_id,member_id,permission,allowed) values(song_editor_test.team(),song_editor_test.id(13),'songs.edit',true);
select set_config('request.jwt.claim.sub',song_editor_test.id(3)::text,false);
set role authenticated;
select song_editor_test.capture_editor('person-grant-beats-role-deny');
do $$declare base jsonb:=song_editor_test.download();result jsonb;begin result:=public.mobile_apply_command(song_editor_test.team(),song_editor_test.command(203,base,'Delegated member saved'));assert result->>'status'='applied';end$$;
reset role;
select set_config('request.jwt.claim.sub','',false);
update public.team_permission_overrides set allowed=false where team_id=song_editor_test.team() and member_id=song_editor_test.id(13);
select set_config('request.jwt.claim.sub',song_editor_test.id(3)::text,false);
set role authenticated;
select song_editor_test.capture_editor('person-deny-proposal');
-- Proposals remain available when direct editing is explicitly denied, matching website behavior.
insert into song_editor_test.pending values('proposal',song_editor_test.proposal(300,(song_editor_test.download()->>'revision')::bigint));
select song_editor_test.capture_proposal('pending',(select command from song_editor_test.pending where name='proposal'));
do $$declare saved jsonb;before_count bigint;after_count bigint;result jsonb;saved_title text;begin
 select receipt into saved from song_editor_test.proposal_cases where name='pending';select song_editor_test.notification_count() into before_count;select songs.title into saved_title from public.songs where id=song_editor_test.id(100);
 assert before_count=2,'Current owner/admin reviewer notifications missing';result:=song_editor_test.capture_proposal('duplicate-lost-reply',(select command from song_editor_test.pending where name='proposal'));assert result=saved,'Exact duplicate proposal receipt differs';select song_editor_test.notification_count() into after_count;assert before_count=after_count,'Duplicate proposal notified reviewers twice';assert(select songs.title=saved_title from public.songs where id=song_editor_test.id(100)),'Proposal published song';
 perform song_editor_test.deny_proposal(jsonb_set((select command from song_editor_test.pending where name='proposal'),'{intent,proposal,reason}','"Changed original reason"'),'22023');
 perform song_editor_test.deny_proposal(jsonb_set(song_editor_test.proposal(301,1),'{intent,proposal,changes}','{"created_by":"99700000-0000-4000-8000-000000000003"}'),'22023');
 perform song_editor_test.deny_proposal(jsonb_set(song_editor_test.proposal(302,1),'{intent,proposal,reason}','" "'),'22023');
end$$;
select song_editor_test.capture_proposal('stale-needs-revision',song_editor_test.proposal(303,1));
reset role;
do $$begin assert(select receipt#>>'{request,status}'='pending' from song_editor_test.proposal_cases where name='pending');assert(select receipt#>>'{request,status}'='needs_revision' from song_editor_test.proposal_cases where name='stale-needs-revision');end$$;
select set_config('request.jwt.claim.sub',song_editor_test.id(4)::text,false);
set role authenticated;
do $$begin assert not exists(select 1 from public.songs where team_id=song_editor_test.team());assert not exists(select 1 from public.team_permission_overrides where team_id=song_editor_test.team());assert not exists(select 1 from public.shared_edit_requests where team_id=song_editor_test.team());end$$;
select song_editor_test.deny_proposal((select command from song_editor_test.pending where name='proposal'),'42501');
reset role;
select set_config('request.jwt.claim.sub','',false);
update public.team_members set status='inactive' where id=song_editor_test.id(13);
select set_config('request.jwt.claim.sub',song_editor_test.id(3)::text,false);
set role authenticated;
select song_editor_test.deny_proposal((select command from song_editor_test.pending where name='proposal'),'42501');
do $$begin assert not exists(select 1 from public.shared_edit_requests where team_id=song_editor_test.team());end$$;
reset role;
select set_config('request.jwt.claim.sub','',false);
update public.team_members set status='active' where id=song_editor_test.id(13);
commit;

